export interface Backing { id: number; alive: boolean; }
export interface Host { open(): Backing; currentId(): number | null; }

/** Reuses its handle while a store still exists at the path. */
export class Store {
  private handle: Backing | null = null;
  constructor(private readonly host: Host) {}

  write(): Backing {
    if (this.handle === null || this.host.currentId() === null) {
      this.handle = this.host.open();
    }
    return this.handle;
  }
}

