import { expect, test } from "bun:test";
import { Store, type Backing, type Host } from "./subject.js";

class FakeHost implements Host {
  private next = 1;
  live: Backing | null = null;
  open(): Backing { this.live = { id: this.next++, alive: true }; return this.live; }
  currentId(): number | null { return this.live ? this.live.id : null; }
  replace(): void { if (this.live) this.live.alive = false; this.live = { id: this.next++, alive: true }; }
}

test("the handle is reused while the store is unchanged", () => {
  const h = new FakeHost(); const s = new Store(h);
  expect(s.write().id).toBe(s.write().id);
});
test("a replaced store is noticed and reopened", () => {
  const h = new FakeHost(); const s = new Store(h);
  const first = s.write();
  h.replace();
  const after = s.write();
  expect(after.id).not.toBe(first.id);
  expect(after.alive).toBe(true);
});
test("writes never go to an orphaned handle", () => {
  const h = new FakeHost(); const s = new Store(h);
  s.write(); h.replace();
  expect(s.write().id).toBe(h.currentId());
});
